{
 "summary": "The Lean theorem asserts that some group G (in Type) exists that is torsion-free, word-hyperbolic and not residually finite. Word-hyperbolic is encoded as: some finite S makes the Cayley graph `mulCayley S` connected, and some natural number δ makes every geodesic triangle of walks δ-thin on vertices. This matches Theorem 1.1. The main caveat is coverage only: Corollary 1.2 (linear obstruction) and Theorem 2.1 (triangle-complex criterion) are not formalized. The bespoke hyperbolicity definition looks like a faithful vertex-level version of the standard Gromov thin-triangles definition.",
 "glossary": [
  {"decl": "TorsionFree", "line": 10, "plain": "For all g and all n>0, g^n = 1 implies g = 1.", "standard_concept": "torsion-free group", "matches_standard": "yes", "note": ""},
  {"decl": "Geodesic", "line": 14, "plain": "A walk from x to y whose length equals the graph distance d(x,y).", "standard_concept": "geodesic edge path in a graph", "matches_standard": "yes", "note": ""},
  {"decl": "SideThin", "line": 18, "plain": "Every vertex on side p lies within graph distance δ of some vertex on side q or side r.", "standard_concept": "δ-thinness of one side of a geodesic triangle", "matches_standard": "yes", "note": "It is checked only at vertices, not at edge midpoints. This changes δ by at most 1, so hyperbolicity is unaffected."},
  {"decl": "WordHyperbolic", "line": 24, "plain": "There is a finite S ⊆ G whose Cayley graph is connected (so S generates G), and some δ ∈ ℕ such that every geodesic triangle (p,q,r) in that graph has all three sides δ-thin.", "standard_concept": "Gromov word-hyperbolic (finitely generated) group", "matches_standard": "yes", "note": "Hyperbolicity does not depend on the finite generating set, so an existential choice of S is standard."}
 ],
 "lean_claims": [
  {"theorem": "OAI.Release075.main", "line": 37, "plain": "There exist a type G and a group structure on G such that three things hold. First, G is torsion-free. Second, some finite S has a connected Cayley graph whose geodesic triangles are uniformly δ-thin. Third, G is not residually finite in Mathlib's sense (Group.ResiduallyFinite)."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "There exists a torsion-free word-hyperbolic group that is not residually finite."},
  {"ref": "Corollary 1.2", "plain": "For this G, every field K, every n ≥ 1 and every homomorphism ρ: G → GL_n(K), the finite residual R_f(G) is contained in ker ρ. In particular G is not linear over any field."},
  {"ref": "Theorem 2.1", "plain": "Let K be a finite Euclidean triangle complex with a link condition (every cyclically reduced closed link walk has angular length ≥ 2π+η). Then π1(K) is torsion-free and hyperbolic, and paths whose turns are all at least π are not nullhomotopic."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "OAI.Release075.main", "relation": "equivalent", "why": "All three properties are encoded with standard meanings."},
  {"paper_ref": "Corollary 1.2", "lean_theorem": null, "relation": "not_formalized", "why": "There is no statement about linear representations."},
  {"paper_ref": "Theorem 2.1", "lean_theorem": null, "relation": "not_formalized", "why": "This is an intermediate criterion and is not stated in Lean."}
 ],
